+-- Amplía las colecciones editoriales con 15 títulos reales por temática.
-- Los libros se identifican por título y autor antes de enlazarlos, para no duplicar fichas existentes.
insert into public.books (id,title,author,genre,year,language,cover,provider,source_id)
