('curated_the_invisible_life_of_addie_larue','The Invisible Life of Addie LaRue','V. E. Schwab','["Fantasía"]','2020','en','https://covers.openlibrary.org/b/title/The%20Invisible%20Life%20of%20Addie%20LaRue-M.jpg','open_library','curated_the_invisible_life_of_addie_larue'),
('curated_the_night_circus','The Night Circus','Erin Morgenstern','["Fantasía"]','2011','en','https://covers.openlibrary.org/b/title/The%20Night%20Circus-M.jpg','open_library','curated_the_night_circus'),
('curated_uprooted','Uprooted','Naomi Novik','["Fantasía"]','2015','en','https://covers.openlibrary.org/b/title/Uprooted-M.jpg','open_library','curated_uprooted'),
('curated_spinning_silver','Spinning Silver','Naomi Novik','["Fantasía"]','2018','en','https://covers.openlibrary.org/b/title/Spinning%20Silver-M.jpg','open_library','curated_spinning_silver'),
('curated_jonathan_strange_mr_norrell','Jonathan Strange & Mr Norrell','Susanna Clarke','["Fantasía"]','2004','en','https://covers.openlibrary.org/b/title/Jonathan%20Strange%20%26%20Mr%20Norrell-M.jpg','open_library','curated_jonathan_strange_mr_norrell'),
('curated_the_ocean_at_the_end_of_the_lane','The Ocean at the End of the Lane','Neil Gaiman','["Fantasía"]','2013','en','https://covers.openlibrary.org/b/title/The%20Ocean%20at%20the%20End%20of%20the%20Lane-M.jpg','open_library','curated_the_ocean_at_the_end_of_the_lane'),
('curated_good_omens','Good Omens','Neil Gaiman & Terry Pratchett','["Fantasía"]','1990','en','https://covers.openlibrary.org/b/title/Good%20Omens-M.jpg','open_library','curated_good_omens'),
