where not exists (select 1 from public.books existing where lower(trim(existing.title))=lower(trim(v.title)) and lower(trim(existing.author))=lower(trim(v.author)));
insert into public.reader_collection_books (collection_id,book_id,sort_order)
select c.id,b.id,10+row_number() over (partition by c.id order by b.title)
from public.reader_collections c cross join public.books b
where c.title='Dark academia: secretos y obsesiones' and ((lower(trim(b.title))='the secret history' and lower(trim(b.author))='donna tartt') or (lower(trim(b.title))='if we were villains' and lower(trim(b.author))='m. l. rio') or (lower(trim(b.title))='babel' and lower(trim(b.author))='r. f. kuang') or (lower(trim(b.title))='the maidens' and lower(trim(b.author))='alex michaelides') or (lower(trim(b.title))='the likeness' and lower(trim(b.author))='tana french') or (lower(trim(b.title))='the goldfinch' and lower(trim(b.author))='donna tartt') or (lower(trim(b.title))='dead poets society' and lower(trim(b.author))='n. h. kleinbaum') or (lower(trim(b.title))='vita nostra' and lower(trim(b.author))='marina dyachenko') or (lower(trim(b.title))='ace of spades' and lower(trim(b.author))='faridah àbíké-íyímídé') or (lower(trim(b.title))='catherine house' and lower(trim(b.author))='elisabeth thomas') or (lower(trim(b.title))='the secret place' and lower(trim(b.author))='tana french') or (lower(trim(b.title))='the lake of dead languages' and lower(trim(b.author))='carol goodman') or (lower(trim(b.title))='the cloisters' and lower(trim(b.author))='katy hays') or (lower(trim(b.title))='an education in malice' and lower(trim(b.author))='mira grant') or (lower(trim(b.title))='the atlas six' and lower(trim(b.author))='olivie blake'))
and not exists (select 1 from public.reader_collection_books cb where cb.collection_id=c.id and cb.book_id=b.id);
insert into public.reader_collection_books (collection_id,book_id,sort_order)
select c.id,b.id,10+row_number() over (partition by c.id order by b.title)
from public.reader_collections c cross join public.books b
where c.title='Lecturas LGTBIQ+ imprescindibles' and ((lower(trim(b.title))='la mala costumbre' and lower(trim(b.author))='alana s. portero') or (lower(trim(b.title))='call me by your name' and lower(trim(b.author))='andré aciman') or (lower(trim(b.title))='aristotle and dante discover the secrets of the universe' and lower(trim(b.author))='benjamin alire sáenz') or (lower(trim(b.title))='the song of achilles' and lower(trim(b.author))='madeline miller') or (lower(trim(b.title))='red, white & royal blue' and lower(trim(b.author))='casey mcquiston') or (lower(trim(b.title))='heartstopper: volume one' and lower(trim(b.author))='alice oseman') or (lower(trim(b.title))='giovanni’s room' and lower(trim(b.author))='james baldwin') or (lower(trim(b.title))='orlando' and lower(trim(b.author))='virginia woolf') or (lower(trim(b.title))='fun home' and lower(trim(b.author))='alison bechdel') or (lower(trim(b.title))='las malas' and lower(trim(b.author))='camila sosa villada') or (lower(trim(b.title))='detransition, baby' and lower(trim(b.author))='torrey peters') or (lower(trim(b.title))='middlesex' and lower(trim(b.author))='jeffrey eugenides') or (lower(trim(b.title))='stone butch blues' and lower(trim(b.author))='leslie feinberg') or (lower(trim(b.title))='el beso de la mujer araña' and lower(trim(b.author))='manuel puig') or (lower(trim(b.title))='el vampiro de la colonia roma' and lower(trim(b.author))='luis zapata'))
and not exists (select 1 from public.reader_collection_books cb where cb.collection_id=c.id and cb.book_id=b.id);
insert into public.reader_collection_books (collection_id,book_id,sort_order)
select c.id,b.id,10+row_number() over (partition by c.id order by b.title)
from public.reader_collections c cross join public.books b
where c.title='Fantasía independiente para perderse' and ((lower(trim(b.title))='piranesi' and lower(trim(b.author))='susanna clarke') or (lower(trim(b.title))='circe' and lower(trim(b.author))='madeline miller') or (lower(trim(b.title))='the invisible life of addie larue' and lower(trim(b.author))='v. e. schwab') or (lower(trim(b.title))='the night circus' and lower(trim(b.author))='erin morgenstern') or (lower(trim(b.title))='uprooted' and lower(trim(b.author))='naomi novik') or (lower(trim(b.title))='spinning silver' and lower(trim(b.author))='naomi novik') or (lower(trim(b.title))='jonathan strange & mr norrell' and lower(trim(b.author))='susanna clarke') or (lower(trim(b.title))='the ocean at the end of the lane' and lower(trim(b.author))='neil gaiman') or (lower(trim(b.title))='good omens' and lower(trim(b.author))='neil gaiman & terry pratchett') or (lower(trim(b.title))='the house in the cerulean sea' and lower(trim(b.author))='tj klune') or (lower(trim(b.title))='the once and future witches' and lower(trim(b.author))='alix e. harrow') or (lower(trim(b.title))='the ten thousand doors of january' and lower(trim(b.author))='alix e. harrow') or (lower(trim(b.title))='the starless sea' and lower(trim(b.author))='erin morgenstern') or (lower(trim(b.title))='the midnight library' and lower(trim(b.author))='matt haig') or (lower(trim(b.title))='the buried giant' and lower(trim(b.author))='kazuo ishiguro'))
and not exists (select 1 from public.reader_collection_books cb where cb.collection_id=c.id and cb.book_id=b.id);

